import json
from lib import *
R = J('r121'); rows = R['rows']; cl, ol, oi = [rows[k] for k in ('闭环(发一条等一条),从实际发送算', '开环(固定 5000/s),从实际发送算', '开环(固定 5000/s),从「应该发送」的时刻算')]
KV = lambda items, hl=(): {'items': items, 'hl': list(hl)}
def bars(items, mx, cur=(), mark=(), done=()): return {'items': items, 'max': mx, 'cur': list(cur), 'mark': list(mark), 'done': list(done)}
def tm(lines, cur=(), mark=()): return {'lines': lines, 'cur': list(cur), 'mark': list(mark)}
steps = [
    step("负载贴近真实一些:key 服从 Zipf 分布(最热的 key 单个占 12.8% 的请求,前 10 个 key 占 34%),读 80% / 写 15% / hash 写 5%,10 万个 key。测试 10 秒,在第 2、5、8 秒各让服务器阻塞 300 ms(DEBUG SLEEP 0.3),模拟三次卡顿。", t=tm(['Zipf 热点 · 80% GET / 15% SET / 5% HSET', '10 秒测试;第 2、5、8 秒各卡 300 ms']), kv=KV([['卡顿', '3 次 × 300 ms']], ['卡顿'])),
    step(f"闭环压测(发一条、等回复、再发下一条,不控制速率):完成 {cl['n']} 个请求,p50 {cl['p50']:.3f} ms、p99 {cl['p99']:.2f} ms、p99.9 {cl['p999']:.1f} ms;最大 {cl['mx']:.0f} ms,超过 100 ms 的请求只有 {cl['slow']} 个。看起来延迟非常好。", b=bars([['p99', cl['p99'], f"{cl['p99']:.2f} ms"], ['p99.9', cl['p999'], f"{cl['p999']:.1f} ms"], ['max', cl['mx'], f"{cl['mx']:.0f} ms"]], 320, done=[0, 1], mark=[2]), kv=KV([['闭环 p99', f"{cl['p99']:.2f} ms"]], ['闭环 p99'])),
    step(f"开环压测(每秒固定 5000 个请求,按时间表发送),但仍从「实际发出」时刻算延迟:{ol['n']} 个请求,p99 {ol['p99']:.2f} ms、p99.9 {ol['p999']:.1f} ms,超过 100 ms 的只有 {ol['slow']} 个。数字和闭环差不多——因为只有正好在卡顿时发出的那个请求被记下了长延迟。", b=bars([['p99', ol['p99'], f"{ol['p99']:.2f} ms"], ['p99.9', ol['p999'], f"{ol['p999']:.1f} ms"], ['max', ol['mx'], f"{ol['mx']:.0f} ms"]], 320, done=[0, 1], mark=[2]), kv=KV([['从实际发送算', f"p99 {ol['p99']:.2f} ms"]], ['从实际发送算'])),
    step(f"同样的开环测试,改成从「按时间表本应发出」的时刻算延迟(把排队时间也算进去):p99 {oi['p99']:.0f} ms、p99.9 {oi['p999']:.0f} ms,超过 100 ms 的请求有 {oi['slow']} 个。卡顿 300 ms 期间本该发出 1500 个请求,它们都晚了——这才是用户真实感受到的延迟。", b=bars([['p99', oi['p99'], f"{oi['p99']:.0f} ms"], ['p99.9', oi['p999'], f"{oi['p999']:.0f} ms"], ['max', oi['mx'], f"{oi['mx']:.0f} ms"]], 320, mark=[0, 1, 2]), kv=KV([['从应发送时刻算', f"p99 {oi['p99']:.0f} ms"]], ['从应发送时刻算'])),
    step(f"同一次故障、同样的服务器,p99 是 {cl['p99']:.2f} ms 还是 {oi['p99']:.0f} ms,只取决于测量方式:闭环压测在服务器卡住时自己也停发了,把最糟的时刻「省略」掉——这叫协调遗漏(coordinated omission)。评估延迟要用开环(固定速率)+ 从预定发送时刻算。", b=bars([['闭环 p99', cl['p99'], f"{cl['p99']:.2f} ms"], ['开环(应发送时刻)p99', oi['p99'], f"{oi['p99']:.0f} ms"]], oi['p99'], done=[0], mark=[1]), kv=KV([['p99 差', f"{cl['p99']:.2f} → {oi['p99']:.0f} ms"]], ['p99 差'])),
]
A = dict(
    n=121, series='redis', tags='Redis,Benchmark,延迟,协调遗漏,真实验证,动画演示',
    desc=f'用带 Zipf 热点的 80/15/5 读写混合负载,在 10 秒测试里注入 3 次 300 ms 的服务器阻塞:闭环压测测得 p99 {cl["p99"]:.2f} ms、超过 100 ms 的请求 {cl["slow"]} 个;开环(每秒 5000)从「本应发送」时刻算,同样的服务器 p99 {oi["p99"]:.0f} ms、{oi["slow"]} 个请求超过 100 ms——测量方式决定了结论(协调遗漏)。',
    lead='真实业务压测有两件事比「压到多高的吞吐」更重要:负载像不像真实业务,以及延迟是怎么测的。这篇用一个带热点、读写混合的负载,在同一个「三次 300 ms 卡顿」的服务器上,用三种测量方式各测一次 p99:数字相差四个数量级。',
    facts=[(f'{cl["p99"]:.2f} ms vs {oi["p99"]:.0f} ms', '同一次故障:闭环压测的 p99 vs 开环、从应发送时刻算的 p99'), (f'{cl["slow"]} vs {oi["slow"]}', '超过 100 ms 的请求数:闭环 vs 开环(应发送时刻)'), ('3 × 300 ms', '10 秒测试里注入的服务器阻塞(DEBUG SLEEP 0.3)')],
    body=[
        sec('负载', '', term('', blk('r121', 1)), '<p>10 万个 key,访问频率服从 Zipf(指数 1.1)——最热的 key 单个占 12.8%,前 10 个占 34%;命令是 80% GET、15% SET、5% HSET。这比 <code>redis-benchmark</code> 默认的「一个 key、全是同一种命令」更接近真实业务(第 120 篇)。</p>'),
        sec('三种测量方式', '同一个 10 秒测试,第 2、5、8 秒各阻塞 300 ms', term('', blk('r121', 2)),
            f'<p><b>闭环</b>(一个连接:发一个、等回复、再发下一个):共完成 {cl["n"]} 个请求,p99 只有 {cl["p99"]:.2f} ms,只有 {cl["slow"]} 个请求超过 100 ms——服务器卡住时,压测程序也停了发,那 300 ms 里本该发生的请求根本没发出去,被「省略」了。<b>开环</b>(固定每秒 5000 个,按时间表发):如果只从实际发出的时刻算延迟,结果和闭环一样({ol["slow"]} 个超过 100 ms);如果从「按时间表本应发出」的时刻算,p99 是 {oi["p99"]:.0f} ms,{oi["slow"]} 个请求超过 100 ms。后者才是真实用户在服务器卡顿时感受到的:卡顿开始之后到达的请求都要排队。</p>'),
        sec('怎么做', '', '<p>1) 用接近真实的命令组合与 key/value 分布;2) 用<b>开环</b>压测:固定速率发送,延迟从「本应发出」的时刻算(常见的压测工具里,带「固定 QPS」并做协调遗漏修正的模式就是这个);3) 单看 p99/p99.9 与最大值,不要只看平均或中位;4) 压测机与被测机分开(第 120 篇)。第 2 条里「常见压测工具」的说法我没有逐个核对具体工具。</p><p>这个实验里的开环客户端是我自己写的单连接 Python 程序,固定速率只有 5000/s;它足以说明测量方式的影响,但不是一个可以用来压满 Redis 的工具。</p>'),
        sec('分步演示:同一次故障,三个 p99', '', demo('Redis 真实业务压测方法', [('t', 'term', '说明'), ('b', 'bars', '延迟'), ('kv', 'kv', '要点')], steps, '本步的对象')),
    ],
    refs=[ENV_R + '。客户端是单连接 Python 程序;开环速率 5000/s;卡顿由 DEBUG SLEEP 0.3 在第 2、5、8 秒制造;工作负载由 random.Random(7) 生成', '没有验证:多连接并发开环压测、更高速率、真实网络、服务器阻塞之外的慢来源(GC、fork)在同一方法下的表现、专业压测工具(如 wrk2、memtier_benchmark)的具体参数'],
)
